/**
 * @summary Get spotlight portfolio for a session
 */
export const getGetPortfolioUrl = (sessionId: string) => {
  return `/api/portfolio/${sessionId}`;
};

export const getPortfolio = async (
  sessionId: string,
  options?: RequestInit,
): Promise<SpotlightPortfolio> => {
  return customFetch<SpotlightPortfolio>(getGetPortfolioUrl(sessionId), {
    ...options,
    method: "GET",
  });
};

export const getGetPortfolioQueryKey = (sessionId: string) => {
  return [`/api/portfolio/${sessionId}`] as const;
};

export const getGetPortfolioQueryOptions = <
  TData = Awaited<ReturnType<typeof getPortfolio>>,
  TError = ErrorType<ErrorResponse>,
>(
  sessionId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getPortfolio>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetPortfolioQueryKey(sessionId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getPortfolio>>> = ({
    signal,
  }) => getPortfolio(sessionId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!sessionId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getPortfolio>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetPortfolioQueryResult = NonNullable<
  Awaited<ReturnType<typeof getPortfolio>>
>;
export type GetPortfolioQueryError = ErrorType<ErrorResponse>;

/**
 * @summary Get spotlight portfolio for a session
 */

export function useGetPortfolio<
  TData = Awaited<ReturnType<typeof getPortfolio>>,
  TError = ErrorType<ErrorResponse>,
>(
  sessionId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getPortfolio>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetPortfolioQueryOptions(sessionId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
